const KEY='dom-vmeste-local-v3',OLD='dom-vmeste-local-v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const defaults=()=>({freeReturns:2,returnPenalty:1,latePenalty:1,reviewEvery:3,qualityPenalty:3,qualityThreshold:2,bonusTarget:5,timerMinutes:20});
const prefs=()=>({phrases:true,motion:true,notifications:'important',quietStart:'22:00',quietEnd:'10:00',timerSound:false,remember:true});
