let suggestionIndex=0;
let db={version:3,rooms:[],roomId:null,actor:null},tab='today',entryView='menu',selectedRoom=null,toast='',toastTimer,editing=null,importDraft=null,backupDraft=null,selfTask=null,chatReply=null,undo=null,saveOK=true,storageLocked=false,joinAttempts=[],reportDate=null;
const room=()=>db.rooms.find(x=>x.id===db.roomId),me=()=>room()?.members.find(x=>x.id===db.actor&&x.active),people=()=>room().members.filter(x=>x.active),member=id=>room()?.members.find(x=>x.id===id);
